BEGIN;
CREATE TABLE IF NOT EXISTS revenue.purification_case(purification_id uuid PRIMARY KEY,income_id uuid NOT NULL REFERENCES revenue.recognized_income(income_id),pool_id text NOT NULL REFERENCES pooling.pool(pool_id),business_date date NOT NULL,currency_code text NOT NULL CHECK(currency_code~'^[A-Z]{3}$'),amount numeric(30,12) NOT NULL CHECK(amount>0),reason text NOT NULL,charity_beneficiary_id text,sharia_decision_reference text,status text NOT NULL CHECK(status IN('PENDING_DOCUMENTATION','READY','PAID')),paid_amount numeric(30,12) NOT NULL DEFAULT 0 CHECK(paid_amount>=0 AND paid_amount<=amount),payment_evidence_id text,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(status='PENDING_DOCUMENTATION' OR(charity_beneficiary_id IS NOT NULL AND sharia_decision_reference IS NOT NULL)),CHECK(status<>'PAID' OR(paid_amount=amount AND payment_evidence_id IS NOT NULL)),UNIQUE(income_id));
CREATE TABLE IF NOT EXISTS revenue.purification_event(event_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),purification_id uuid NOT NULL REFERENCES revenue.purification_case(purification_id),event_type text NOT NULL,amount numeric(30,12),evidence_id text,occurred_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE OR REPLACE FUNCTION revenue.reject_purification_event_mutation()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'Purification events are append-only';END;$$;DROP TRIGGER IF EXISTS purification_event_immutable ON revenue.purification_event;CREATE TRIGGER purification_event_immutable BEFORE UPDATE OR DELETE ON revenue.purification_event FOR EACH ROW EXECUTE FUNCTION revenue.reject_purification_event_mutation();
COMMIT;
